      "inputs": {
        "schema": "schema_preview"
      },
      "target_resources": [],
      "outputs": ["spatial_temporal_data"]
    },
    {
      "task": "generate_metadata",
      "player": "metadata_generator",
      "rationale": "Synthesize the required seven metadata fields (name, description, keywords, spatialCoverage, temporalCoverage, spatial, temporal) from the gathered artifacts.",
      "inputs": {
        "metadata_standard": "metadata_standard",
        "schema": "schema_preview",
        "statistics": "field_statistics",
        "spatial_temporal": "spatial_temporal_data"
      },
      "target_resources": [],
      "outputs": ["metadata_output"]
    }
  ]
}

